import java.util.Scanner;

public class Main {
    static long v;
    static long[] cand = new long[17];

    static int rec(int ind, long val) {
        val = Math.abs(val);
        if (ind == 0) {
            return (int) val;
        }
        int a1 = (int) (val / cand[ind]);
        int a2 = a1 + 1;
        int option1 = a1 * (ind + 1) + rec(ind - 1, val - a1 * cand[ind]);
        int option2 = a2 * (ind + 1) + rec(ind - 1, val - a2 * cand[ind]);
        return Math.min(option1, option2);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        v = sc.nextLong();
        cand[0] = 1;
        for (int i = 1; i < 17; ++i) {
            cand[i] = cand[i - 1] * 10 + 1;
        }
        System.out.println(rec(16, v));
        sc.close();
    }
}
